SELECT id, original_name AS originalName, stored_name AS storedName, content_type AS contentType, file_size AS fileSize, upload_user_id AS uploadUserId, upload_time AS uploadTime FROM file_info
original_name LIKE CONCAT('%', #{keyword}, '%')
AND upload_user_id = #{userId}
ORDER BY upload_time DESC, id DESC
LIMIT #{offset}, #{size}

